/** Desktop page host. The shared screen talks to Chromium through this file. */
@Composable
fun rememberDesktopHost(): ChromeHost = ChromeHost(
    openPage = { hooks -> DesktopBrowserPage(hooks) },
    pageSlot = { page, modifier -> DesktopPageView(page as DesktopBrowserPage, modifier) },
    fullscreen = { page, modifier -> DesktopPageView(page as DesktopBrowserPage, modifier) },
    backHandler = { _, _ -> },
    launchAddress = { _ -> false },
    ringGesture = { _ -> },
    wire = { _: SnackbarHostState -> },
    chooseZip = { deliver ->
        val chooser = JFileChooser()
        chooser.fileFilter = FileNameExtensionFilter("Extension", "zip", "crx")
        if (chooser.showOpenDialog(null) == JFileChooser.APPROVE_OPTION) {
            deliver(chooser.selectedFile.readBytes())
        }
    },
)

/** Brave's adblock-rust, the same engine and filter lists the Android app uses. */
class DesktopBrave(private val dir: File) : ListBlocker {
    @Volatile override var enabled: Boolean = true
    @Volatile private var ready = false
    private var engine: AdblockEngine? = null
    private val engineFile = File(dir, "engine.bin")
    private val stampFile = File(dir, "stamp.txt")

    override var status by mutableStateOf("Brave engine is loading filter lists")
        private set

    fun start() {
        thread(name = "brave-adblock", isDaemon = true) {
            try {
                dir.mkdirs()
                val created = AdblockEngine.create()
                val fresh = stampFile.exists() &&
                    System.currentTimeMillis() - stampFile.readText().trim().toLong() < MAX_AGE_MS
                if (fresh && created.deserializeFrom(engineFile)) {
                    loadResources(created)
                    finish(created, "Brave engine, using cached EasyList, EasyPrivacy, and uBlock")
                    return@thread
                }
                val lists = FILTER_LISTS.map { fetch(it) }.filter { it.isNotBlank() }
                if (lists.isEmpty()) {
                    status = "Brave engine could not download filter lists"
                    return@thread
                }
                created.loadFilterList(lists.joinToString("\n"))
                loadResources(created)
                created.serializeTo(engineFile)
                stampFile.writeText(System.currentTimeMillis().toString())
                finish(created, "Brave engine, EasyList + EasyPrivacy + uBlock")
            } catch (error: Throwable) {
                status = "Brave engine failed to start: ${error.message}"
                System.err.println(status)
            }
        }
    }

    fun shouldBlock(url: String, sourceUrl: String, requestType: String): Boolean {
        val active = engine ?: return false
        if (!enabled || !ready) return false
        val decision = active.checkNetworkRequest(url, sourceUrl, requestType)
        return decision.matched && !decision.exception
    }

    /** Hides elements the network rules cannot remove, such as inline ad slots. */
    fun cosmeticScript(pageUrl: String): String? {
        val active = engine ?: return null
        if (!enabled || !ready || !pageUrl.startsWith("http")) return null
        val css = active.cosmeticResources(pageUrl)?.css().orEmpty()
        if (css.isBlank()) return null
        val quoted = "\"" + css.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n") + "\""
        return """
            (function(){
              var style = document.getElementById('sledge-cosmetics');
              if (!style) {
                style = document.createElement('style');
                style.id = 'sledge-cosmetics';
                (document.head || document.documentElement).appendChild(style);
              }
              style.textContent = $quoted;
            })();
        """.trimIndent()
    }

    private fun finish(created: AdblockEngine, message: String) {
        engine = created
        ready = true
        status = message
        println(message)
    }

    private fun loadResources(target: AdblockEngine) {
        val json = DesktopBrave::class.java.getResourceAsStream("/adblock/resources.json")
            ?.bufferedReader()?.use { it.readText() } ?: return
        target.loadResources(json)
    }

    private fun fetch(url: String): String {
        val cache = File(dir, url.substringAfterLast('/').substringBefore('?'))
        return try {
            val body = URI(url).toURL().readText()
            if (body.isNotBlank()) cache.writeText(body)
            body
        } catch (error: Exception) {
            System.err.println("Filter download failed for $url: ${error.message}")
            if (cache.exists()) cache.readText() else ""
        }
    }

    private companion object {
        const val MAX_AGE_MS = 24L * 60L * 60L * 1000L
        val FILTER_LISTS = listOf(
            "https://easylist.to/easylist/easylist.txt",
            "https://easylist.to/easylist/easyprivacy.txt",
            "https://raw.githubusercontent.com/uBlockOrigin/uAssets/master/filters/filters.txt",
        )
    }
}

private fun CefRequest.ResourceType?.adblockType(): String = when (this) {
    CefRequest.ResourceType.RT_MAIN_FRAME -> "document"
    CefRequest.ResourceType.RT_SUB_FRAME -> "subdocument"
    CefRequest.ResourceType.RT_STYLESHEET -> "stylesheet"
    CefRequest.ResourceType.RT_SCRIPT,
    CefRequest.ResourceType.RT_WORKER,
    CefRequest.ResourceType.RT_SHARED_WORKER,
    CefRequest.ResourceType.RT_SERVICE_WORKER,
    -> "script"
    CefRequest.ResourceType.RT_IMAGE, CefRequest.ResourceType.RT_FAVICON -> "image"
    CefRequest.ResourceType.RT_FONT_RESOURCE -> "font"
    CefRequest.ResourceType.RT_OBJECT, CefRequest.ResourceType.RT_PLUGIN_RESOURCE -> "object"
    CefRequest.ResourceType.RT_MEDIA -> "media"
    CefRequest.ResourceType.RT_XHR -> "xmlhttprequest"
    CefRequest.ResourceType.RT_PING, CefRequest.ResourceType.RT_CSP_REPORT -> "ping"
    else -> "other"
}

object DesktopEngine {
    var client: KCEFClient? = null
    var brave: DesktopBrave? = null

    /**
     * The engine bundle ships its own GLES and SwiftShader libraries, and the
     * helper loads them before the system driver. On Mesa that copy can crash
     * the GPU process, which leaves the page blank.
     */
    fun prepare(bundle: File) {
        if (!bundle.isDirectory) return
        val names = listOf(
            "libGLESv2.so",
            "libEGL.so",
            "libvk_swiftshader.so",
            "libvulkan.so.1",
            "vk_swiftshader_icd.json",
        )
        val present = names.map { File(bundle, it) }.filter { it.isFile }
        if (present.isEmpty()) return
        val aside = File(bundle, "gpu-aside")
        aside.mkdirs()
        present.forEach { file -> file.renameTo(File(aside, file.name)) }
    }

    fun arguments(bundle: File, helper: String): Array<String> = arrayOf(
        "--browser-subprocess-path=$helper",
        "--resources-dir-path=${bundle.absolutePath}",
        "--locales-dir-path=${File(bundle, "locales").absolutePath}",
        "--use-gl=egl",
        "--disable-gpu-sandbox",
        "--disable-features=Vulkan",
    )
}

/** Chromium reports events per browser. This routes each one to its tab. */
private object DesktopNavigation {
    private val pages = CopyOnWriteArrayList<DesktopBrowserPage>()
    @Volatile private var installed = false

    /** Runs on Chromium's IO thread for every subresource; main-frame loads are never blocked. */
    private val blocking = object : CefResourceRequestHandlerAdapter() {
        override fun onBeforeResourceLoad(
            browser: CefBrowser?,
            frame: CefFrame?,
            request: CefRequest?,
        ): Boolean {
            val brave = DesktopEngine.brave ?: return false
            val url = request?.url ?: return false
            val type = request.resourceType
            if (type == CefRequest.ResourceType.RT_MAIN_FRAME) return false
            if (!url.startsWith("http://") && !url.startsWith("https://")) return false
            val source = frame?.url?.takeIf { it.startsWith("http") } ?: browser?.url.orEmpty()
            return brave.shouldBlock(url, source, type.adblockType())
        }
    }

    @Synchronized
    fun install(client: KCEFClient) {
        if (installed) return
        installed = true
        client.addLifeSpanHandler(object : CefLifeSpanHandlerAdapter() {
            override fun onBeforePopup(
                browser: CefBrowser,
                frame: CefFrame,
                targetUrl: String,
                targetFrameName: String,
            ): Boolean {
                openInPage(browser, targetUrl)
                return true
            }
        })
        client.addRequestHandler(object : CefRequestHandlerAdapter() {
            override fun onOpenURLFromTab(
                browser: CefBrowser,
                frame: CefFrame,
                targetUrl: String,
                userGesture: Boolean,
            ): Boolean {
                openInPage(browser, targetUrl)
                return true
            }

            override fun onBeforeBrowse(
                browser: CefBrowser,
                frame: CefFrame,
                request: CefRequest,
                userGesture: Boolean,
                isRedirect: Boolean,
            ): Boolean {
                if (!frame.isMain) return false
                val url = request.url ?: return false
                if (!url.startsWith("http://") && !url.startsWith("https://")) return false
                return page(browser)?.blockForLookalike(url) == true
            }

            override fun getResourceRequestHandler(
                browser: CefBrowser?,
                frame: CefFrame?,
                request: CefRequest?,
                isNavigation: Boolean,
                isDownload: Boolean,
                requestInitiator: String?,
                disableDefaultHandling: BoolRef?,
            ): CefResourceRequestHandler = blocking
        })
        client.addDisplayHandler(object : CefDisplayHandlerAdapter() {
            override fun onAddressChange(browser: CefBrowser, frame: CefFrame, url: String) {
                if (frame.isMain) page(browser)?.showAddress(url)
            }

            override fun onTitleChange(browser: CefBrowser, title: String) {
                page(browser)?.showTitle(title)
            }

            override fun onConsoleMessage(
                browser: CefBrowser,
                level: CefSettings.LogSeverity,
                message: String,
                source: String,
                line: Int,
            ): Boolean {
                page(browser)?.showConsole(level.toConsoleLevel(), message, source, line)
                return false
            }
        })
        client.addLoadHandler(object : CefLoadHandlerAdapter() {
            override fun onLoadingStateChange(
                browser: CefBrowser,
                isLoading: Boolean,
                canGoBack: Boolean,
                canGoForward: Boolean,
            ) {
                page(browser)?.showProgress(if (isLoading) 10 else 100)
            }

            override fun onLoadEnd(browser: CefBrowser, frame: CefFrame, httpStatusCode: Int) {
                if (!frame.isMain) return
                val url = browser.url.orEmpty()
                DesktopEngine.brave?.cosmeticScript(url)?.let { frame.executeJavaScript(it, url, 0) }
                page(browser)?.showFinished(url)
            }

            override fun onLoadError(
                browser: CefBrowser,
                frame: CefFrame,
                errorCode: CefLoadHandler.ErrorCode,
                errorText: String,
                failedUrl: String,
            ) {
                if (!frame.isMain || errorCode == CefLoadHandler.ErrorCode.ERR_ABORTED) return
                val target = page(browser) ?: return
                target.showConsole(ConsoleLevel.Error, "$errorText ($failedUrl)", failedUrl, 0)
                target.showFinished(failedUrl)
            }
        })
    }

    fun attach(page: DesktopBrowserPage) {
        if (page !in pages) pages += page
    }

    fun detach(page: DesktopBrowserPage) {
        pages -= page
    }

    /** Handlers receive the native browser, not the wrapper the page holds. */
    private fun page(browser: CefBrowser): DesktopBrowserPage? {
        val id = browser.identifier
        return pages.firstOrNull { it.owns(id) } ?: pages.singleOrNull()
    }

    private fun openInPage(browser: CefBrowser, targetUrl: String?) {
        val url = targetUrl?.takeIf { it.isNotBlank() } ?: return
        SwingUtilities.invokeLater { browser.loadURL(url) }
    }
}

/** Address-bar text Chromium can load. Words become a search. */
internal fun navigableWebUrl(url: String): String? {
    val trimmed = url.trim()
    if (trimmed.isEmpty()) return null
    val scheme = trimmed.substringBefore(':', missingDelimiterValue = "").lowercase()
    return when (scheme) {
        "http", "https", "file" -> trimmed
        "about" -> trimmed.takeIf { it.equals("about:blank", ignoreCase = true) }
        "javascript", "data", "content", "intent", "blob",
        "mailto", "tel", "sms", "market",
        -> null
        else -> when {
            ' ' in trimmed || '.' !in trimmed ->
                "https://duckduckgo.com/?q=${URLEncoder.encode(trimmed, Charsets.UTF_8)}"
            else -> "https://$trimmed"
        }
    }
}

@Composable
private fun DesktopPageView(page: DesktopBrowserPage, modifier: Modifier) {
    val component = page.component
    if (component == null) Box(modifier) else SwingPanel(factory = { component }, modifier = modifier)
}

class DesktopBrowserPage(private val hooks: PageHooks) : BrowserPage {
    private var browser: KCEFBrowser? = null
    private var current: String? = null
    override val url: String? get() = current
    override val fullscreen: Boolean get() = false
    var component by mutableStateOf<Component?>(null)
        private set

    override fun loadUrl(next: String) {
        val url = navigableWebUrl(next) ?: return
        if (hooks.onLookalike(url)) return
        current = url
        hooks.onPageStarted(url)
        val existing = browser
        if (existing == null) open(url) else existing.loadURL(url)
    }

    fun owns(id: Int): Boolean = id > 0 && browser?.identifier == id

    fun blockForLookalike(url: String): Boolean = hooks.onLookalike(url)

    fun showAddress(url: String) {
        if (url.isBlank()) return
        SwingUtilities.invokeLater {
            current = url
            hooks.onPageStarted(url)
        }
    }

    fun showTitle(title: String) {
        SwingUtilities.invokeLater { hooks.onTitle(title) }
    }

    fun showProgress(progress: Int) {
        SwingUtilities.invokeLater { hooks.onProgress(progress) }
    }

    fun showConsole(level: ConsoleLevel, message: String, source: String, line: Int) {
        SwingUtilities.invokeLater { hooks.onConsole(level, message, source, line) }
    }

    fun showFinished(url: String) {
        val shown = url.ifBlank { current }.orEmpty()
        if (shown.isBlank()) return
        SwingUtilities.invokeLater {
            current = shown
            hooks.onPageFinished(shown, null)
        }
    }

    override fun goBack() { browser?.goBack() }
    override fun goForward() { browser?.goForward() }
    override fun reload() { browser?.reload() }
    override fun canGoBack(): Boolean = browser?.canGoBack() == true
    override fun canGoForward(): Boolean = browser?.canGoForward() == true
    override fun applySettings(settings: BrowserSettings) {}
    override fun onPause() {}
    override fun onResume() {}
    override fun destroy() {
        val page = browser ?: return
        browser = null
        component = null
        DesktopNavigation.detach(this)
        page.close(true)
    }
    override fun exitFullscreen() {}
    override fun setFindListener(listener: (Int, Int, Boolean) -> Unit) {}
    override fun clearMatches() { browser?.stopFinding(true) }
    override fun findAllAsync(query: String) { browser?.find(query, true, false, false) }
    override fun findNext(forward: Boolean) {}
    override fun evaluate(script: String) {
        browser?.executeJavaScript(script, current.orEmpty(), 0)
    }

    /**
     * The native browser is created once its component is on screen. Creating
     * it earlier on X11 leaves Chromium drawing into a window that is gone.
     */
    private fun open(url: String) {
        val holder = DesktopEngine.client ?: return
        DesktopNavigation.install(holder)
        val created = holder.createBrowser(url, CefRendering.DEFAULT, false)
        browser = created
        DesktopNavigation.attach(this)
        component = created.uiComponent
    }
}

private fun CefSettings.LogSeverity.toConsoleLevel(): ConsoleLevel = when (this) {
    CefSettings.LogSeverity.LOGSEVERITY_ERROR,
    CefSettings.LogSeverity.LOGSEVERITY_FATAL,
    -> ConsoleLevel.Error
    CefSettings.LogSeverity.LOGSEVERITY_WARNING -> ConsoleLevel.Warn
    CefSettings.LogSeverity.LOGSEVERITY_INFO -> ConsoleLevel.Log
    else -> ConsoleLevel.Info
}
